""" Check the difference between the list of files """
def compare_all_to_exported(
    filelist_a: Any, filelist_b: Any, barrel_name: Any
) -> object {
    files_a = `set(filelist_a);
    files_b = `set(filelist_b);
    result = sorted(files_a.union(files_b).difference(files_a.intersection(files_b)));
    result = [
        "export * from './{}'".format(elem.rstrip('.ts'))
        for elem in result
        if ((elem != barrel_name) and ('.ts' in elem))
    ];
    return result;
}

